using UnityEngine;
using UnityEngine.InputSystem;
public partial class DungeonPrototype {
 Vector2 pauseMapCenter;float pauseMapCellPixels=32;bool pauseMapDragging;
 void CenterPauseMap(){pauseMapCenter=position;pauseMapDragging=false;}
 void PanPauseMap(Vector2 delta){pauseMapCenter+=delta;pauseMapCenter.x=Mathf.Clamp(pauseMapCenter.x,0,map[0].Length-1);pauseMapCenter.y=Mathf.Clamp(pauseMapCenter.y,0,map.Length-1);}
 void PauseMapKeys(Keyboard k){Vector2 step=Vector2.zero;if(k.rightArrowKey.wasPressedThisFrame)step.x=2;if(k.leftArrowKey.wasPressedThisFrame)step.x=-2;if(k.upArrowKey.wasPressedThisFrame)step.y=2;if(k.downArrowKey.wasPressedThisFrame)step.y=-2;if(k.cKey.wasPressedThisFrame)CenterPauseMap();PanPauseMap(step);}
 void DrawExploredMap(Rect r,int left,int bottom,int cols,int rows){NeonDungeonUI.Map(r,cols,rows);Rect g=NeonDungeonUI.MapInterior(r);float cw=g.width/cols,ch=g.height/rows;for(int y=0;y<rows;y++)for(int x=0;x<cols;x++){int mx=left+x,my=bottom+y;if(explored==null||!explored[mx,my])continue;GUI.color=map[my][mx]=='#'?Layout.discoveredWall:map[my][mx]=='~'?new Color(.035f,.015f,.07f):Layout.discoveredFloor;GUI.DrawTexture(new Rect(g.x+x*cw+1,g.y+(rows-1-y)*ch+1,Mathf.Max(.5f,cw-2),Mathf.Max(.5f,ch-2)),Texture2D.whiteTexture);}GUI.color=Color.white;if(position.x>=left&&position.x<left+cols&&position.y>=bottom&&position.y<bottom+rows)NeonDungeonUI.Label(new Rect(g.x+(position.x-left)*cw,g.y+(rows-1-(position.y-bottom))*ch,cw,ch),new[]{"▲","▶","▼","◀"}[heading],true);}
 void DrawPauseMap(float w,float y){Rect bounds=new Rect(w/2-465,y+90,680,405);int cols=Mathf.Min(map[0].Length,Mathf.Max(3,Mathf.FloorToInt(bounds.width*(181f/224)/pauseMapCellPixels))),rows=Mathf.Min(map.Length,Mathf.Max(3,Mathf.FloorToInt(bounds.height*(170f/205)/pauseMapCellPixels)));int left=Mathf.Clamp(Mathf.RoundToInt(pauseMapCenter.x)-cols/2,0,map[0].Length-cols),bottom=Mathf.Clamp(Mathf.RoundToInt(pauseMapCenter.y)-rows/2,0,map.Length-rows);Rect r=SquareMapRect(bounds,cols,rows);DrawExploredMap(r,left,bottom,cols,rows);Rect g=NeonDungeonUI.MapInterior(r);
  Rect small=SquareMapRect(new Rect(w/2+235,y+90,230,405),map[0].Length,map.Length);DrawExploredMap(small,0,0,map[0].Length,map.Length);Rect overview=NeonDungeonUI.MapInterior(small);float cw=overview.width/map[0].Length,ch=overview.height/map.Length;Rect selected=new Rect(overview.x+left*cw,overview.y+(map.Length-bottom-rows)*ch,cols*cw,rows*ch);GUI.color=Color.yellow;GUI.DrawTexture(new Rect(selected.x,selected.y,selected.width,2),Texture2D.whiteTexture);GUI.DrawTexture(new Rect(selected.x,selected.yMax-2,selected.width,2),Texture2D.whiteTexture);GUI.DrawTexture(new Rect(selected.x,selected.y,2,selected.height),Texture2D.whiteTexture);GUI.DrawTexture(new Rect(selected.xMax-2,selected.y,2,selected.height),Texture2D.whiteTexture);GUI.color=Color.white;
  var ev=Event.current;if(ev.type==EventType.ScrollWheel&&g.Contains(ev.mousePosition)){pauseMapCellPixels=Mathf.Clamp(pauseMapCellPixels-ev.delta.y*2,18,60);ev.Use();}if(ev.type==EventType.MouseDown&&ev.button==0){if(g.Contains(ev.mousePosition)){pauseMapDragging=true;ev.Use();}else if(overview.Contains(ev.mousePosition)){pauseMapCenter=new Vector2((ev.mousePosition.x-overview.x)/cw,map.Length-1-(ev.mousePosition.y-overview.y)/ch);ev.Use();}}if(ev.type==EventType.MouseDrag&&pauseMapDragging){PanPauseMap(new Vector2(-ev.delta.x/(g.width/cols),ev.delta.y/(g.height/rows)));ev.Use();}if(ev.type==EventType.MouseUp)pauseMapDragging=false;
  if(GUI.Button(new Rect(w/2-200,y+495,180,32),"CENTRAR EN TI — C"))CenterPauseMap();NeonDungeonUI.Label(new Rect(w/2-460,y+575,920,30),"Flechas / arrastrar: mover · Rueda: zoom · Clic en mapa lateral: ir a esa área",true);
 }
}
